        var detail = baggageService.getClaimDetail("CLAIM-2");
        assertThat(detail.chain()).extracting(c -> c.eventType() + ":" + c.seq())
                .containsExactly("HOLD:0");
        assertThat(detail.chain().get(0).legId()).isNull();

        now = T0.plusSeconds(30);
